import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"区域和可用区","description":"","frontmatter":{"title":"区域和可用区"},"headers":[],"relativePath":"dedicatedserver/product-intro/regions-and-zones.md","filePath":"dedicatedserver/product-intro/regions-and-zones.md","lastUpdated":1793696072000}'),o={name:"dedicatedserver/product-intro/regions-and-zones.md"};function i(l,t,n,p,h,s){return d(),r("div",null,[...t[0]||(t[0]=[e('<p>本文介绍 RakSmart 物理服务器支持的全部区域和可用区。</p><h3 id="区域" tabindex="-1">区域 <a class="header-anchor" href="#区域" aria-label="Permalink to &quot;区域&quot;">​</a></h3><p>区域是指在全球范围内划分的、具备独立基础设施的地理部署单元。不同地域之间完全隔离，以保证所提供服务的稳定性与容错性。RakSmart 物理服务器目前支持的区域有美洲、亚洲和欧洲。</p><ul><li><p>不同区域的服务器默认不能通过内网通信。</p></li><li><p>如果不同区域之间的服务器之间有通信需求，可以通过公网 IP 进行通信。</p></li></ul><hr><h3 id="可用区" tabindex="-1">可用区 <a class="header-anchor" href="#可用区" aria-label="Permalink to &quot;可用区&quot;">​</a></h3><p>可用区是同一区域内物理隔离的独立数据中心单元。同一可用区内实例之间的网络时延更小，用户访问速度更快。</p><hr><h3 id="区域和可用区列表" tabindex="-1">区域和可用区列表 <a class="header-anchor" href="#区域和可用区列表" aria-label="Permalink to &quot;区域和可用区列表&quot;">​</a></h3><p>下表列出 RakSmart 物理服务器支持的全部区域和可用区，有关地域和可用区的更多信息请参见 <a href="https://cn.raksmart.com/" target="_blank" rel="noreferrer">RakSmart 官网首页</a> - 全球数据中心网络。</p><table tabindex="0"><thead><tr><th>区域</th><th>可用区</th><th>可用区标识</th></tr></thead><tbody><tr><td>美洲</td><td>硅谷</td><td>SV</td></tr><tr><td>美洲</td><td>洛杉矶</td><td>LA</td></tr><tr><td>美洲</td><td>西雅图</td><td>SEA</td></tr><tr><td>亚洲</td><td>香港</td><td>HK</td></tr><tr><td>亚洲</td><td>台湾</td><td>TW</td></tr><tr><td>亚洲</td><td>东京</td><td>TYO</td></tr><tr><td>亚洲</td><td>首尔</td><td>SEL</td></tr><tr><td>亚洲</td><td>新加坡</td><td>SG</td></tr><tr><td>亚洲</td><td>吉隆坡</td><td>KUL</td></tr><tr><td>欧洲</td><td>法兰克福</td><td>FRA</td></tr></tbody></table><hr><h3 id="如何选择区域和可用区" tabindex="-1">如何选择区域和可用区 <a class="header-anchor" href="#如何选择区域和可用区" aria-label="Permalink to &quot;如何选择区域和可用区&quot;">​</a></h3><p>用户与资源部署地域的距离越近，网络时延越低，访问速度越快。建议您根据业务场景对时延的要求选择区域和可用区。</p><blockquote><p><strong>重要</strong></p><p>购买并开通 RakSmart 物理服务器资源后，无法更换区域和可用区。</p></blockquote><h4 id="如何选择区域" tabindex="-1">如何选择区域 <a class="header-anchor" href="#如何选择区域" aria-label="Permalink to &quot;如何选择区域&quot;">​</a></h4><p>在购买 RakSmart 物理服务器时，请结合以下因素合理选择区域。</p><ol><li><p>地理位置</p><p>一般情况下建议选择和您目标用户所在区域最为接近的数据中心，可以进一步提升用户访问速度。</p></li><li><p>资源价格及资源覆盖</p><p>不同区域的资源规格和产品覆盖可能有差异，请根据您的需求及预算选择合适的区域。</p></li><li><p>产品之间的关系</p><p>如果多个 RakSmart 产品一起搭配使用，需要注意：不同区域的主机、存储、负载均衡等服务，内网不互通。</p></li></ol><h4 id="如何选择可用区" tabindex="-1">如何选择可用区 <a class="header-anchor" href="#如何选择可用区" aria-label="Permalink to &quot;如何选择可用区&quot;">​</a></h4><p>在同一区域内，各可用区之间可以实现故障隔离，即如果一个可用区出现故障，则不会影响其他可用区的正常运行。</p><ul><li><p>目标用户地理位置：选择在地理位置上最靠近目标服务用户的地域，以防止出现访问时延，影响访问速度。</p></li><li><p>容灾部署：如果购买的物理服务器位于同一个地域，建议将业务分散部署在多个可用区，以确保故障隔离，实现跨可用区容灾。</p></li></ul>',21)])])}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
